pub(crate) fn for_language(language: &str) -> CodeIcon {
    if language.eq_ignore_ascii_case("rust") || language.eq_ignore_ascii_case("rs") {
        RUST
    } else if language.eq_ignore_ascii_case("tsx") || language.eq_ignore_ascii_case("jsx") {
        REACT
    } else if language.eq_ignore_ascii_case("typescript") || language.eq_ignore_ascii_case("ts") {
        TYPESCRIPT
    } else if matches_ignore_ascii_case(language, &["bash", "sh", "shell", "shellscript", "zsh"]) {
        SHELL
    } else if matches_ignore_ascii_case(language, &["html", "html5"]) {
        HTML
    } else if matches_ignore_ascii_case(language, &["python", "py"]) {
        PYTHON
    } else if language.eq_ignore_ascii_case("toml") {
        TOML
    } else if matches_ignore_ascii_case(language, &["yaml", "yml"]) {
        YAML
    } else if matches_ignore_ascii_case(language, &["markdown", "md", "mdx"]) {
        MARKDOWN
    } else if language.eq_ignore_ascii_case("c") {
        C
    } else if matches_ignore_ascii_case(language, &["docker", "dockerfile"]) {
        DOCKER
    } else if language.eq_ignore_ascii_case("nginx") {
        NGINX
    } else if matches_ignore_ascii_case(language, &["json", "jsonc", "json5"]) {
        JSON
    } else {
        FILE
    }
}

fn matches_ignore_ascii_case(value: &str, candidates: &[&str]) -> bool {
    candidates
        .iter()
        .any(|candidate| value.eq_ignore_ascii_case(candidate))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn normalizes_common_fence_aliases() {
        assert_eq!(for_language("rs").name, "rust");
        assert_eq!(for_language("TS").name, "typescript");
        assert_eq!(for_language("tsx").name, "react");
        assert_eq!(for_language("zsh").name, "shell");
        assert_eq!(for_language("yml").name, "yaml");
        assert_eq!(for_language("mdx").name, "markdown");
        assert_eq!(for_language("dockerfile").name, "docker");
    }

    #[test]
    fn uses_file_icon_for_unknown_or_unlabeled_fences() {
        assert_eq!(for_language("").name, "file");
        assert_eq!(for_language("proa-filetree").name, "file");
    }
}
